@Scheduled(fixedDelay = 2000)
public void relay() {
    for (Outbox m : outboxMapper.findNew(100)) {
        try {
            kafkaTemplate.send(m.getTopic(), m.getBizKey(), m.getPayload()).get(3, TimeUnit.SECONDS);
            outboxMapper.markSent(m.getId());
        } catch (Exception e) {
            outboxMapper.incrRetry(m.getId());   // 超过次数告警人工处理
        }
    }
}

