import java.util.*;

public class ConsistentHash<T> {
    private final TreeMap<Long, T> ring = new TreeMap<>();
    private final int virtualNodes;

    public ConsistentHash(Collection<T> nodes, int virtualNodes) {
        this.virtualNodes = virtualNodes;
        nodes.forEach(this::add);
    }
    public void add(T node) {
        for (int i = 0; i < virtualNodes; i++) ring.put(hash(node + "#" + i), node);
    }
    public void remove(T node) {
        for (int i = 0; i < virtualNodes; i++) ring.remove(hash(node + "#" + i));
    }
    public T get(String key) {
        Map.Entry<Long, T> e = ring.ceilingEntry(hash(key));   // 顺时针第一个
        return (e != null ? e : ring.firstEntry()).getValue();  // 越过末尾回到环首
    }
    private long hash(String s) {                               // FNV-1a，分布较均匀
        long h = 0xcbf29ce484222325L;
        for (byte b : s.getBytes()) { h ^= b; h *= 0x100000001b3L; }
        return h & 0xffffffffL;
    }
}
