// 不透明 token 方案
public String login(User u) {
    String token = UUID.randomUUID().toString();
    redis.opsForValue().set("login:" + token, toJson(u.toSession()), Duration.ofMinutes(30));
    return token;                                  // 前端放 Authorization 头
}
public UserSession check(String token) {
    String v = redis.opsForValue().getAndExpire("login:" + token, Duration.ofMinutes(30)); // 续期
    if (v == null) throw new UnauthorizedException();
    return fromJson(v);
}

