public interface StockTccAction {
    @TwoPhaseBusinessAction(name = "deductStock", commitMethod = "confirm",
                            rollbackMethod = "cancel", useTCCFence = true) // 防幂等/空回滚/悬挂
    boolean tryDeduct(@BusinessActionContextParameter(paramName = "skuId") Long skuId,
                      @BusinessActionContextParameter(paramName = "count") Integer count);
