synchronized long nextId() {
    long now = System.currentTimeMillis();
    if (now < lastTs) {                        // 时钟回拨
        if (lastTs - now < 5) now = waitUntil(lastTs);
        else throw new IllegalStateException("clock moved backwards");
    }
    if (now == lastTs) {
        seq = (seq + 1) & 4095;                // 12 位序列号
        if (seq == 0) now = waitUntil(lastTs + 1);
    } else seq = 0;
    lastTs = now;
    return ((now - EPOCH) << 22) | (workerId << 12) | seq;
}

